import{_ as s,C as i,o as d,c as u,a6 as l,j as t,E as r,w as n,a}from"./chunks/framework.DfoD60a6.js";const k=JSON.parse('{"title":"06 · 同步工具怎麼做","description":"","frontmatter":{},"headers":[],"relativePath":"spec/06-synchronization-tools.md","filePath":"spec/06-synchronization-tools.md","lastUpdated":1795330291000}'),h={name:"spec/06-synchronization-tools.md"},m={tabindex:"0"};function p(_,e,f,b,S,T){const o=i("SpecTerm");return d(),u("div",null,[e[13]||(e[13]=l('<h1 id="_06-·-同步工具怎麼做" tabindex="-1">06 · 同步工具怎麼做 <a class="header-anchor" href="#_06-·-同步工具怎麼做" aria-label="Permalink to &quot;06 · 同步工具怎麼做&quot;">​</a></h1><p>WUWAOS 提供使用者程式可請求的 Mutex 和 Semaphore。核心另外用 Gate 保護檔案系統、虛擬記憶體和 Block 裝置的長操作，並以事件通知等待者。它們都能讓等待者暫停，但保護的對象和喚醒後的動作不同。</p><h2 id="先決定要保護哪一件事" tabindex="-1">先決定要保護哪一件事 <a class="header-anchor" href="#先決定要保護哪一件事" aria-label="Permalink to &quot;先決定要保護哪一件事&quot;">​</a></h2><p>Mutex 用來保護一段操作，鎖住後可更新一組必須一致的欄位。Semaphore 用來記錄可消耗的份數。例如容量為 4 的佇列可用一個初值 4 的 Semaphore 表示空位，再用一把鎖保護實際入列。空位的數量和佇列內容的互斥各有用途。</p><p>等待可以靠重複檢查，也可以由核心把呼叫者移到 Waiting，讓其他執行緒使用 Hart。短小的底層共享核心鎖有自旋路徑，使用者同步物件等不到資源時可以阻塞。用哪種等待方式，取決於保護範圍、持有時間與目前能否睡眠。</p><h2 id="使用者程式的-mutex-與-semaphore" tabindex="-1">使用者程式的 Mutex 與 Semaphore <a class="header-anchor" href="#使用者程式的-mutex-與-semaphore" aria-label="Permalink to &quot;使用者程式的 Mutex 與 Semaphore&quot;">​</a></h2>',6)),t("table",m,[e[6]||(e[6]=t("thead",null,[t("tr",null,[t("th",null,"工具"),t("th",null,"核心維護的資料"),t("th",null,"等待與喚醒")])],-1)),t("tbody",null,[t("tr",null,[t("td",null,[r(o,{term:"mutex",definition:"有一位擁有者的鎖，用來保護臨界區。持有者完成後才能解鎖。WUWAOS 用執行緒身分判斷誰有權解鎖。"},{default:n(()=>[...e[0]||(e[0]=[a("Mutex",-1)])]),_:1})]),e[1]||(e[1]=t("td",null,"目前擁有者是一條執行緒。",-1)),e[2]||(e[2]=t("td",null,[a("有擁有者時加入等待佇列。解鎖只能由擁有者發出，解鎖後喚醒隊首。原擁有者退出時標記鎖已受損，等待者收到 "),t("code",null,"SYNC_ERR_OWNER_DIED"),a("。")],-1))]),t("tr",null,[t("td",null,[r(o,{term:"semaphore",definition:"記錄可用份數的同步物件。等到一份資源時減一，歸還或生產資源時加一。即使當下沒有等待者，已增加的份數也會保留。"},{default:n(()=>[...e[3]||(e[3]=[a("Semaphore",-1)])]),_:1})]),e[4]||(e[4]=t("td",null,"還可以取用幾份資源。",-1)),e[5]||(e[5]=t("td",null,[t("code",null,"wait()"),a(" 在數量大於零時取走一份，否則等候。"),t("code",null,"post()"),a(" 加回一份並喚醒隊首，即使當下無人等待，這份資源也會保留。")],-1))])])]),e[14]||(e[14]=l('<p>兩種物件共用 8 格核心表，程式以 handle（物件編號）操作。等待者被喚醒後會重新嘗試取得資源，因此喚醒順序是 FIFO，取得資源的順序仍受後續派發影響。尚有持有者或等待者時不能銷毀物件。同一執行緒重複鎖住自己的使用者 Mutex 會回傳錯誤。</p><h3 id="跟著-demo-sync-看兩次等待" tabindex="-1">跟著 <code>demo sync</code> 看兩次等待 <a class="header-anchor" href="#跟著-demo-sync-看兩次等待" aria-label="Permalink to &quot;跟著 `demo sync` 看兩次等待&quot;">​</a></h3><p>父行程先持有 Mutex，並建立初始值為 0 的 Semaphore。子行程一開始嘗試拿鎖，因父行程還持有而進入等待。父釋放 Mutex，子取得鎖、釋放鎖，接著在 <code>semaphore_wait()</code> 等待。父行程 <code>post()</code> 後，子行程重新取得執行機會並消耗那一份。畫面上的訊息能看出互斥、計數與排程分別在哪一步發生。 <a href="https://github.com/johnson931128/WUWAOS/blob/main/user/shell/sync_demo.c" target="_blank" rel="noreferrer">同步示範程式</a></p><h2 id="核心的-gate-與事件" tabindex="-1">核心的 Gate 與事件 <a class="header-anchor" href="#核心的-gate-與事件" aria-label="Permalink to &quot;核心的 Gate 與事件&quot;">​</a></h2>',4)),t("p",null,[r(o,{term:"kernel-gate",definition:"核心內部用來保護操作邊界的鎖。擁有者可以配對地重複進入和離開，其他執行緒會等待或在不能睡眠的路徑收到忙碌結果。"},{default:n(()=>[...e[7]||(e[7]=[a("KernelGate",-1)])]),_:1}),e[8]||(e[8]=a(" 以 Thread 和 TID 辨識擁有者。同一擁有者可以再次進入，每次進入需配對離開。其他執行緒遇到已占用的 Gate，可以等擁有者釋放。中斷處理與排程器輪詢等不能睡眠的路徑，遇到忙碌 Gate 時回傳 ",-1)),e[9]||(e[9]=t("code",null,"ERR_BUSY",-1)),e[10]||(e[10]=a("。",-1))]),t("p",null,[r(o,{term:"kernel-event",definition:"核心用來通知等待者的物件。Generation 區分同一欄位的不同使用週期，sequence 表示通知有沒有更新。等待可以帶期限，結果留給被喚醒的執行緒收取。"},{default:n(()=>[...e[11]||(e[11]=[a("事件來源",-1)])]),_:1}),e[12]||(e[12]=a(" 用 generation 辨識物件的這一次使用，用 sequence 記下自上次查閱後是否發生通知。等待者可同時設定 deadline（最後等到的時間）。通知、逾時或取消會把結果留下，讓執行緒回來後知道等待為何結束。共享核心鎖序列化短暫的核心狀態更新，Gate 則保護可能跨越執行緒睡眠的操作邊界。",-1))]),e[15]||(e[15]=l('<p>可以用 Shell <code>demo sync</code> 觀察 Mutex 和 Semaphore。Core 測試覆蓋 Gate 所有權與 TID 的行為，QEMU 既有驗收覆蓋實際 I/O 事件等待和喚醒。 <a href="https://github.com/johnson931128/WUWAOS/blob/3a3b273/kernel/ipc/sync.c" target="_blank" rel="noreferrer">同步實作</a> · <a href="https://github.com/johnson931128/WUWAOS/blob/3a3b273/kernel/proc/gate.c" target="_blank" rel="noreferrer">Gate</a> · <a href="https://github.com/johnson931128/WUWAOS/blob/3a3b273/kernel/proc/event.c" target="_blank" rel="noreferrer">Event</a> · <a href="./../SPEC-22-synchronization.html">同步規格</a> · <a href="./../merge-2026-11-10.html">非同步 I/O 驗收</a></p><h2 id="恐龍書與課堂筆記" tabindex="-1">恐龍書與課堂筆記 <a class="header-anchor" href="#恐龍書與課堂筆記" aria-label="Permalink to &quot;恐龍書與課堂筆記&quot;">​</a></h2><p>恐龍書第 10 版 §6.4–6.8、§7.1。讀寫者、哲學家用餐、Monitor 及其他同步方案一併收錄。</p><ul><li><a href="./../theory/06-synchronization.html">同步工具與經典同步問題</a></li><li><a href="./../theory/08-deadlocks.html">死結與資源配置</a></li><li><a href="./../theory/systems-glossary.html">同步、死結、記憶體名詞對照</a></li></ul>',4))])}const y=s(h,[["render",p]]);export{k as __pageData,y as default};
